package com.smarthub.plus;
import android.app.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.*;import android.view.*;import android.widget.*;
/** Shared broadcast menu skin; every item maps to an actual local or receiver action. */
final class ReceiverPanelStyle {
 static final int GOLD=0xffffdf78,CYAN=0xff39dcff;
 static int dp(Context c,float n){return Math.round(n*c.getResources().getDisplayMetrics().density);}
 static GradientDrawable panel(Context c){return RxSkin.glass(c,true);}
 static StateListDrawable row(Context c){return RxSkin.focus(c);}
  interface Choice {void selected(int index);}
 static void choose(Activity a,String title,String[] labels,int selected,Choice click){boolean ar=a.getSharedPreferences("smarthub",0).getBoolean("arabic",true);LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding(dp(a,18),dp(a,14),dp(a,18),dp(a,14));box.setBackground(panel(a));TextView heading=new TextView(a);heading.setText("‹  "+title+"  ›");heading.setTextColor(RxSkin.accent(a));heading.setTextSize(23);heading.setGravity(Gravity.CENTER);box.addView(heading,new LinearLayout.LayoutParams(-1,dp(a,46)));ListView list=new ListView(a);list.setSelector(android.R.color.transparent);list.setDividerHeight(0);list.setAdapter(new BaseAdapter(){public int getCount(){return labels.length;}public Object getItem(int p){return labels[p];}public long getItemId(int p){return p;}public View getView(int p,View old,ViewGroup parent){TextView v=new TextView(a);v.setText((p==selected?"✓   ":"     ")+labels[p]);v.setTextSize(21);v.setTextColor(p==selected?RxSkin.accent(a):0xfff1f1f5);v.setGravity(Gravity.CENTER_VERTICAL);v.setTextDirection(View.TEXT_DIRECTION_FIRST_STRONG);v.setSingleLine(true);v.setPadding(dp(a,18),0,dp(a,18),0);v.setBackground(row(a));v.setLayoutParams(new AbsListView.LayoutParams(-1,dp(a,45)));return v;}});int screen=(int)(a.getResources().getDisplayMetrics().heightPixels/a.getResources().getDisplayMetrics().density);box.addView(list,new LinearLayout.LayoutParams(-1,Math.min(dp(a,Math.max(100,screen-170)),dp(a,45*labels.length))));TextView hint=new TextView(a);hint.setText(ar?"OK اختيار     BACK رجوع":"OK Select     BACK Back");hint.setTextSize(12);hint.setTextColor(RxSkin.accent(a));hint.setPadding(0,dp(a,12),0,0);box.addView(hint);AlertDialog d=new AlertDialog.Builder(a).setView(box).create();list.setOnItemClickListener((p,v,index,id)->{d.dismiss();click.selected(index);});d.setOnKeyListener((dialog,key,event)->{if(key!=KeyEvent.KEYCODE_MENU)return false;if(event.getAction()==KeyEvent.ACTION_DOWN&&event.getRepeatCount()==0){d.dismiss();ReceiverNavigation.openLauncher(a);}return true;});d.show();Window w=d.getWindow();if(w!=null){w.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));w.setLayout(Math.min(dp(a,580),a.getResources().getDisplayMetrics().widthPixels-dp(a,48)),-2);}list.setSelection(Math.max(0,selected));list.requestFocus();}
}
